sys_script_client.script:
function onSubmit() {
    var leaveType = g_form.getValue('leave_type');
    var balance = parseInt(g_form.getValue('leave_balance_at_request'), 10);
    var startDateStr = g_form.getValue('start_date');
    var endDateStr = g_form.getValue('end_date');
    var diffInDays = 0;

    // 1. Validate dates
    if (startDateStr === '' || endDateStr === '') {
        g_form.addErrorMessage('Please enter both start date and end date.');
        return false;
    }

    var startMs = getDateFromFormat(startDateStr, g_user_date_format);
    var endMs = getDateFromFormat(endDateStr, g_user_date_format);

    if (startMs === 0 || endMs === 0) {
        g_form.addErrorMessage('Please enter valid dates.');
        return false;
    }

    if (endMs < startMs) {
        g_form.addErrorMessage('End date cannot be before start date.');
        return false;
    }

    // 2. Calculate leave duration (Note: This is still raw days, not working days)
    var diffInMs = endMs - startMs;
    diffInDays = Math.round(diffInMs / (1000 * 60 * 60 * 24)) + 1;

    // 3. Medical certificate validation
    if (leaveType === 'sick' && diffInDays > 2) {
        var hasAttachment = false;

        try {
            // Check the native header paperclip element
            var attachmentElement = document.getElementById('header_attachment_list_label');

            if (attachmentElement) {
                // If the style is not hidden, an attachment exists
                var style = window.getComputedStyle(attachmentElement);
                if (style.display !== 'none' && style.visibility !== 'hidden') {
                    hasAttachment = true;
                }
            }
        } catch (e) {
            console.warn("DOM access blocked. Ensure 'Isolate script' is unchecked on the Client Script.");
        }

        // 3. Block submission and show error if missing
        if (!hasAttachment) {
            g_form.addErrorMessage('A medical certificate is required for Sick Leave exceeding 2 days. Please click the paperclip icon at the top right to attach it.');
            return false;
        }
    }

    // 4. Leave balance validation
    if (!isNaN(balance) && diffInDays > balance) {
        var proceed = confirm(
            'Warning: You are requesting ' + diffInDays +
            ' days, but your current balance is only ' + balance +
            ' days. Do you wish to proceed and submit this request?'
        );

        if (!proceed) {
            return false;
        }
    }

    // 5. Allow submission
    return true;
}
